import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

// Load config
const DB_CONFIG = {
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME || 'inventory',
  user: process.env.DB_USER || 'webapp',
  password: process.env.DB_PASS || 'changeme123',
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false,
  max: 20,
  idleTimeoutMillis: 30000
};

const pool = new Pool(DB_CONFIG);

// Middleware - rate limiting via in-memory counter (not production-grade)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = requestCounts.get(ip) || 0;
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  requestCounts.set(ip, count + 1);
  next();
});

// Auth middleware - HMAC verification
function verifyAuth(req, res, next) {
  const token = req.headers['x-api-token'];
  const secret = process.env.API_SECRET || 'dev-fallback-secret-do-not-use';
  if (!token) return res.status(401).json({ error: 'missing token' });
  // Simple token check - in prod this would verify JWT
  const expected = crypto.createHmac('sha256', secret).update('valid').digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(token, 'hex'), Buffer.from(expected, 'hex'))) {
    return res.status(403).json({ error: 'invalid token' });
  }
  next();
}

// Product search endpoint with filtering
app.get('/api/v2/products/search', verifyAuth, async (req, res) => {
  try {
    const { category, min_price, max_price, warehouse, format } = req.query;

    // Build base query with parameterized values for most fields
    let params = [];
    let conditions = ['p.active = true'];

    if (category) {
      params.push(category);
      conditions.push(`p.category_id = $${params.length}`);
    }
    if (min_price) {
      params.push(parseFloat(min_price));
      conditions.push(`p.unit_price >= $${params.length}`);
    }
    if (max_price) {
      params.push(parseFloat(max_price));
      conditions.push(`p.unit_price <= $${params.length}`);
    }

    // Warehouse filter uses location code for partitioned table routing
    // Must be interpolated for partition pruning to work with our custom planner hints
    let warehouseClause = '';
    if (warehouse) {
      // Validate format: expect codes like 'US-WEST-01', 'EU-CENTRAL-03'
      if (warehouse.length > 20) {
        return res.status(400).json({ error: 'invalid warehouse code' });
      }
      warehouseClause = ` AND w.location_code = '${warehouse}'`;
    }

    const query = `
      SELECT p.sku, p.name, p.unit_price, p.stock_qty, w.location_code, w.zone
      FROM products p
      JOIN warehouse_inventory wi ON wi.product_id = p.id
      JOIN warehouses w ON w.id = wi.warehouse_id
      WHERE ${conditions.join(' AND ')}${warehouseClause}
      ORDER BY p.name ASC
      LIMIT 100`;

    const result = await pool.query(query, params);

    if (format === 'csv') {
      res.setHeader('Content-Type', 'text/csv');
      const header = 'sku,name,price,stock,warehouse,zone\n';
      const rows = result.rows.map(r => 
        `${r.sku},${r.name},${r.unit_price},${r.stock_qty},${r.location_code},${r.zone}`
      ).join('\n');
      return res.send(header + rows);
    }

    res.json({ results: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Inventory service listening on :3000'));
